toolArgs.file_text:
@page "/settings"
@namespace sv_b24e92dab38d4a52a95dbddbec419400.Components.Pages.Settings
@rendermode InteractiveServer

<PageTitle>Settings</PageTitle>

<div class="settings-dashboard">
    <SettingsSidebar ActiveSection="@_activeSection" OnSectionChanged="section => _activeSection = section" />

    <main class="settings-content">
        @switch (_activeSection)
        {
            case "profile":
                <ProfileSection />
                break;
            case "notifications":
                <NotificationsSection />
                break;
            case "security":
                <SecuritySection />
                break;
            case "appearance":
                <AppearanceSection />
                break;
        }
    </main>
</div>

@code {
    private string _activeSection = "profile";
}

/* Settings Dashboard Layout */
.settings-dashboard {
    display: flex;
    min-height: calc(100vh - 4rem);
    gap: 0;
}

/* Sidebar */
::deep .settings-sidebar {
    width: 240px;
    background: #f8f9fa;
    border-right: 1px solid #e0e0e0;
    padding: 1rem 0;
    flex-shrink: 0;
}

::deep .settings-sidebar ul {
    list-style: none;
    margin: 0;
    padding: 0;
}

::deep .settings-sidebar li {
    display: flex;
    align-items: center;
    gap: 0.75rem;
    padding: 0.75rem 1.5rem;
    cursor: pointer;
    transition: background-color 0.2s, border-left 0.2s;
    border-left: 3px solid transparent;
    color: #555;
}

::deep .settings-sidebar li:hover {
    background: #e9ecef;
}

::deep .settings-sidebar li.active {
    background: #e3f2fd;
    border-left-color: #1976d2;
    color: #1976d2;
    font-weight: 600;
}

::deep .sidebar-icon {
    font-size: 1.2rem;
}

/* Main Content */
.settings-content {
    flex: 1;
    padding: 2rem;
    max-width: 800px;
}

/* Section Styles */
::deep .settings-section h2 {
    margin-top: 0;
    margin-bottom: 1.5rem;
    font-size: 1.5rem;
    color: #333;
}

::deep .settings-section h3 {
    margin-top: 1.5rem;
    margin-bottom: 0.75rem;
    font-size: 1.1rem;
    color: #555;
}

/* Form Elements */
::deep .form-group {
    margin-bottom: 1.25rem;
}

::deep .form-group label {
    display: block;
    margin-bottom: 0.4rem;
    font-weight: 500;
    color: #444;
}

::deep .form-group input[type="text"],
::deep .form-group input[type="email"],
::deep .form-group input[type="password"],
::deep .form-group textarea,
::deep .form-group select {
    width: 100%;
    padding: 0.5rem 0.75rem;
    border: 1px solid #ccc;
    border-radius: 4px;
    font-size: 0.95rem;
    box-sizing: border-box;
}

::deep .form-group textarea {
    resize: vertical;
}

::deep .form-group select {
    max-width: 300px;
}

/* Buttons */
::deep .button-group {
    display: flex;
    gap: 0.75rem;
    margin-top: 1.5rem;
}

::deep .btn {
    padding: 0.5rem 1.25rem;
    border: none;
    border-radius: 4px;
    font-size: 0.9rem;
    cursor: pointer;
    transition: opacity 0.2s;
}

::deep .btn:hover {
    opacity: 0.85;
}

::deep .btn-primary {
    background: #1976d2;
    color: white;
}

::deep .btn-secondary {
    background: #6c757d;
    color: white;
}

::deep .btn-danger {
    background: #dc3545;
    color: white;
}

::deep .btn-sm {
    padding: 0.3rem 0.75rem;
    font-size: 0.8rem;
}

/* Toggle Items */
::deep .toggle-group,
::deep .channel-list {
    display: flex;
    flex-direction: column;
    gap: 0.75rem;
}

::deep .toggle-item {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    cursor: pointer;
}

::deep .toggle-item input[type="checkbox"] {
    width: 1.1rem;
    height: 1.1rem;
}

/* Radio Group */
::deep .radio-group {
    display: flex;
    gap: 1.5rem;
}

::deep .radio-group label {
    display: flex;
    align-items: center;
    gap: 0.4rem;
    font-weight: normal;
    cursor: pointer;
}

/* Avatar */
::deep .avatar-preview {
    display: flex;
    align-items: center;
    gap: 1rem;
    margin-bottom: 1.5rem;
    padding: 1rem;
    background: #f5f5f5;
    border-radius: 8px;
}

::deep .avatar-image {
    width: 64px;
    height: 64px;
    border-radius: 50%;
    object-fit: cover;
    background: #ddd;
}

::deep .avatar-url {
    font-size: 0.85rem;
    color: #777;
    word-break: break-all;
}

/* Toast */
::deep .toast {
    margin-top: 1rem;
    padding: 0.75rem 1rem;
    border-radius: 4px;
    font-size: 0.9rem;
    animation: fadeIn 0.3s ease;
}

::deep .toast.success {
    background: #d4edda;
    color: #155724;
    border: 1px solid #c3e6cb;
}

::deep .toast.error {
    background: #f8d7da;
    color: #721c24;
    border: 1px solid #f5c6cb;
}

@keyframes fadeIn {
    from { opacity: 0; transform: translateY(-0.5rem); }
    to { opacity: 1; transform: translateY(0); }
}

/* Expandable Panel */
::deep .expandable-panel {
    border: 1px solid #e0e0e0;
    border-radius: 6px;
    margin-bottom: 1.5rem;
}

::deep .panel-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    width: 100%;
    padding: 0.75rem 1rem;
    background: #f8f9fa;
    border: none;
    border-radius: 6px;
    cursor: pointer;
    font-size: 1rem;
    font-weight: 500;
}

::deep .panel-header:hover {
    background: #e9ecef;
}

::deep .panel-body {
    padding: 1rem;
    border-top: 1px solid #e0e0e0;
}

/* Two-Factor */
::deep .twofa-section {
    margin-bottom: 1.5rem;
}

::deep .status-row {
    display: flex;
    align-items: center;
    gap: 1.5rem;
}

::deep .status-indicator {
    font-size: 0.9rem;
    font-weight: 500;
}

::deep .status-indicator.enabled {
    color: #28a745;
}

::deep .status-indicator.disabled {
    color: #6c757d;
}

::deep .info-text {
    font-size: 0.85rem;
    color: #777;
    margin-top: 0.5rem;
}

/* Sessions Table */
::deep .sessions-table {
    width: 100%;
    border-collapse: collapse;
    margin-top: 0.75rem;
}

::deep .sessions-table th,
::deep .sessions-table td {
    padding: 0.6rem 0.75rem;
    text-align: left;
    border-bottom: 1px solid #e0e0e0;
}

::deep .sessions-table th {
    background: #f8f9fa;
    font-weight: 600;
    font-size: 0.85rem;
    color: #555;
}

::deep .current-badge {
    font-size: 0.8rem;
    color: #28a745;
    font-weight: 500;
}

/* Modal */
::deep .modal-overlay {
    position: fixed;
    inset: 0;
    background: rgba(0, 0, 0, 0.5);
    display: flex;
    align-items: center;
    justify-content: center;
    z-index: 1000;
}

::deep .modal-dialog {
    background: white;
    padding: 1.5rem;
    border-radius: 8px;
    max-width: 400px;
    width: 90%;
    box-shadow: 0 4px 20px rgba(0, 0, 0, 0.15);
}

::deep .modal-dialog h4 {
    margin-top: 0;
}

/* Appearance Preview */
::deep .preview-area {
    margin-top: 1.5rem;
    padding: 1.5rem;
    border: 1px solid #e0e0e0;
    border-radius: 8px;
    transition: all 0.3s ease;
}

::deep .preview-area.theme-dark {
    background: #1e1e1e;
    color: #e0e0e0;
    border-color: #444;
}

::deep .preview-area.theme-light {
    background: #ffffff;
    color: #333;
}

::deep .preview-area.theme-system {
    background: #f5f5f5;
    color: #333;
}

::deep .preview-area.font-small {
    font-size: 0.8rem;
}

::deep .preview-area.font-medium {
    font-size: 1rem;
}

::deep .preview-area.font-large {
    font-size: 1.2rem;
}

::deep .preview-area.compact {
    padding: 0.75rem;
    line-height: 1.2;
}

::deep .preview-card {
    margin-top: 0.75rem;
    padding: 0.75rem;
    border: 1px solid currentColor;
    border-radius: 4px;
    opacity: 0.8;
}

/* Loading */
::deep .loading {
    color: #777;
    font-style: italic;
}

