+
+::deep .preview-area.theme-dark {
+    background: #1e1e1e;
+    color: #e0e0e0;
+    border-color: #444;
+}
+
+::deep .preview-area.theme-light {
+    background: #ffffff;
+    color: #333;
+}
+
+::deep .preview-area.theme-system {
+    background: #f5f5f5;
+    color: #333;
+}
+
+::deep .preview-area.font-small {
+    font-size: 0.8rem;
+}
+
+::deep .preview-area.font-medium {
+    font-size: 1rem;
+}
+
+::deep .preview-area.font-large {
+    font-size: 1.2rem;
+}
+
+::deep .preview-area.compact {
+    padding: 0.75rem;
+    line-height: 1.2;
+}
+
+::deep .preview-card {
+    margin-top: 0.75rem;
+    padding: 0.75rem;
+    border: 1px solid currentColor;
+    border-radius: 4px;
